void count_down(int n)
{
    if (n == 0)
        return;
    printf("%i\n", n);
    count_down(n - 1);
}

Funksiya:
int sum_to(int n)
{
    if (n == 0)
        return 0;
    return n + sum_to(n - 1);
}

Funksiya:
int factorial(int n)
{
    if (n == 0)
        return 1;
    int smaller = factorial(n - 1);
    return n * smaller;
}

Funksiya:
int fibonacci(int n)
{
    if (n == 0)
        return 0;
    if (n == 1)
        return 1;
    int left = fibonacci(n - 1);
    int right = fibonacci(n - 2);
    return left + right;
}

Rekursiv algoritm:
void hanoi(int n, char from, char to, char aux)
{
    if (n == 1)
    {
        printf("Move disk 1 from %c to %c\n", from, to);
        return;
    }
    hanoi(n-1, from, aux, to);
    printf("Move disk %d from %c to %c\n", n, from, to);
    hanoi(n-1, aux, to, from);
}
